<?php declare(strict_types=1); namespace Annam; $title='Checkout settings'; ?>
<section class="o-card"><h2>Delivery rules</h2><p>Meals use approved <a href="/manage/zones/">delivery areas</a>, category availability, minimum and one fee per order. Breakfast, Lunch and Snacks can be combined; Dinner is separate. Snacks outside Chennai use courier delivery, without a courier pincode whitelist.</p><p><?= e(Delivery::COURIER) ?></p></section><form method="post" class="o-form"><?= csrf() ?><section class="o-card"><h2>Snacks courier orders</h2><label class="o-check"><input type="checkbox" name="courier_enabled" value="1" <?= !empty($settings['courier_enabled'])?'checked':'' ?>><span class="o-switch-ui"><i></i></span><b>Enable courier orders</b></label><label class="o-field">Minimum shop items subtotal (₹)<input type="number" name="courier_minimum" min="0" step="0.01" value="<?= e($settings['courier_minimum']??'0') ?>" required></label><input type="hidden" name="courier_fee" value="0"><p>Local delivery uses the selected area's fee. Courier fees are confirmed after dispatch in the order details.</p></section><section class="o-card"><h2>Meal holidays & payment</h2><label class="o-field">Closed meal dates<textarea name="closed_dates" placeholder="YYYY-MM-DD, one per line"><?= e(implode("\n",$settings['closed_dates']??[])) ?></textarea></label><label class="o-field">Manual payment instructions<textarea name="payment_instructions" maxlength="1000"><?= e($settings['payment_instructions']??'') ?></textarea></label></section><section class="o-card"><h2>Courier WhatsApp notices</h2><p>Notices remain held while integration is offline. Use approved Meta templates before enabling.</p><?php foreach(['courier_notifications_enabled'=>'Enable courier notices','courier_online_enabled'=>'Enable separate online courier payments'] as $k=>$label): ?><label class="o-check"><input type="checkbox" name="<?= e($k) ?>" value="1" <?= !empty($settings[$k])?'checked':'' ?>><span class="o-switch-ui"><i></i></span><b><?= e($label) ?></b></label><?php endforeach; ?><?php foreach(['courier_team_phone'=>'Team WhatsApp number','courier_customer_template'=>'Customer notice template','courier_team_template'=>'Team notice template','courier_template_language'=>'Template language'] as $k=>$label): ?><label class="o-field"><?= e($label) ?><input name="<?= e($k) ?>" value="<?= e($settings[$k]??($k==='courier_template_language'?'en':'')) ?>"></label><?php endforeach; ?></section><button class="o-btn o-btn-primary">Save settings</button></form><?php if(!empty($settings['courier_notifications_enabled'])): ?><form method="post" action="/manage/courier-notices/release/" class="o-card"><?= csrf() ?><p>Release previously held courier notices only after approving the customer and team templates.</p><button class="o-btn">Release held courier notices</button></form><?php endif; ?>